const $=id=>document.getElementById(id);
const modes={generate:['GENERATION / 01','让水流的势能，成为电能。','高负荷时段，上水库放水，水流经输水系统驱动水轮机，带动发电机向电网送电。','水的势能 → 机械能 → 电能','↓','水流向下 · 驱动水轮机','→ 电网'],pump:['PUMPING / 02','将低谷电能，储存在高处。','低负荷或电力富余时段，电网向电动机供电，驱动水泵将下水库的水提升到上水库，以重力势能形式储存。','电能 → 机械能 → 水的势能','↑','水流向上 · 水泵提升','← 电网'],standby:['STANDBY / 03','保持可用，等待调度。','教学示意中，机组停止抽水和发电，保留水量与机组可用性以响应后续调度。实际启动与切换需满足设备及安全条件。','无抽水、发电能量转换','—','水流停止 · 待命状态','· 备用']};
document.querySelectorAll('[data-mode]').forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const m=modes[b.dataset.mode];['mode-label','mode-title','mode-description','chain','flow-arrow','flow-text','grid-flow'].forEach((id,i)=>$(id).textContent=m[i]);$('rotor').style.animationPlayState=b.dataset.mode==='standby'?'paused':'running';$('rotor').style.animationDirection=b.dataset.mode==='pump'?'reverse':'normal';}});
function calculate(){const h=+$('head').value,q=+$('flow').value,e=+$('eff').value,p=1000*9.81*q*h*(e/100)/1e6;$('head-out').textContent=h+' m';$('flow-out').textContent=q+' m³/s';$('eff-out').textContent=e+' %';$('power').textContent=p.toFixed(2);$('capacity').textContent='约为清原单机额定容量的'+(p/3).toFixed(1)+'%';$('capacity-bar').style.width=Math.min(p/3,100)+'%';$('substitution').textContent=`P = 1000 × 9.81 × ${q} × ${h} × ${(e/100).toFixed(2)} ÷ 10⁶ = ${p.toFixed(2)} MW`;$('warning').textContent=p>300?'估算值超过300 MW额定容量；实际运行不能据此超出机组限值。':'';return {h,q,e,p};}
['head','flow','eff'].forEach(id=>$(id).addEventListener('input',calculate));$('reset').onclick=()=>{$('head').value=400;$('flow').value=85;$('eff').value=90;calculate()};$('export').onclick=()=>{const {h,q,e,p}=calculate();const text=`清原抽水蓄能 · 教学计算记录\n生成时间：${new Date().toLocaleString('zh-CN')}\n性质：独立教学假设，非工程实测或正式设计结果\n净水头 H = ${h} m\n体积流量 Q = ${q} m³/s\n发电综合效率 η = ${e}%\n水密度 ρ = 1000 kg/m³\n重力加速度 g = 9.81 m/s²\nP = ρgQHη = ${p.toFixed(2)} MW\n对照单机额定容量：300 MW\n未考虑机组特性曲线、空化与运行限值；净水头应扣除水力损失。\n`;const u=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='清原抽水蓄能_教学计算记录.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};calculate();
